 * The two kinds of rate limiter, each keeping one independent state per key.
 */

const NAME_PATTERN = /^[A-Za-z0-9_./:-]+$/

export function isValidToken(text) {
  return NAME_PATTERN.test(text)
}

/**
 * A token bucket. Tokens are tracked as an exact count of "per"ths of a
 * token, so that partial refills never lose precision across advances.
 */
export class BucketPolicy {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.capacityUnits = capacity * per
    this.states = new Map()
  }

  #advance(key, tick) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { units: this.capacityUnits, tick }
      this.states.set(key, state)
      return state
    }
    const elapsed = tick - state.tick
    if (elapsed > 0n) {
      const added = this.refill * elapsed
      let units = state.units + added
      if (units > this.capacityUnits) units = this.capacityUnits
      state.units = units
      state.tick = tick
    }
    return state
  }

  advance(key, tick) {
    this.#advance(key, tick)
  }

  allows(key, tick) {
    const state = this.#advance(key, tick)
    return state.units >= this.per
  }

  record(key, tick) {
    const state = this.#advance(key, tick)
    state.units -= this.per
  }
}

/**
 * A sliding window. Remembers the ticks of the requests it has recorded for
 * each key, forgetting the ones that have fallen out of the span.
 */
export class WindowPolicy {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  #forget(key, tick) {
    let list = this.states.get(key)
    if (list === undefined) {
      list = []
      this.states.set(key, list)
    }
    const threshold = tick - this.span
    let start = 0
    while (start < list.length && list[start] <= threshold) start++
    if (start > 0) list.splice(0, start)
    return list
  }

  advance(key, tick) {
    this.#forget(key, tick)
  }

  allows(key, tick) {
    const list = this.#forget(key, tick)
    return BigInt(list.length) < this.limit
  }

  record(key, tick) {
    const list = this.#forget(key, tick)
    list.push(tick)
  }
}
"}

