{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e3-attempts-t5/cell-A37wrX/src/simulate.js","content":"import { LimiterError } from './errors.js'
import { BucketPolicy, WindowPolicy, isValidToken } from './policies.js'

const UINT_PATTERN = /^(0|[1-9][0-9]*)$/

function splitLines(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function parseUint(text, field, min) {
  if (!UINT_PATTERN.test(text)) {
    throw { field, min }
  }
  const value = BigInt(text)
  if (value < min) {
    throw { field, min }
  }
  return value
}

function fail(line, reason) {
  throw new LimiterError(line, reason)
}

function requireUint(line, text, field, min) {
  try {
    return parseUint(text, field, min)
  } catch {
    fail(line, `${field} must be an integer of at least ${min}`)
  }
}

/**
 * Parses and simulates the limiter file described by `input`, producing the
 * per-event verdicts. Throws a LimiterError on the first line that fails to
 * parse or validate.
 */
export function simulate(input) {
  const lines = splitLines(input)

  const policies = new Map()
  const routePrefixes = new Set()
  const routes = []
  let firstEventSeen = false
  let lastTick = null

  const events = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const raw = lines[i]
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'bucket' || directive === 'window' || directive === 'route') {
      if (firstEventSeen) fail(lineNo, 'declarations must come before the first event')
    }

    if (directive === 'bucket') {
      if (tokens.length !== 5) fail(lineNo, 'expected bucket <name> <capacity> <refill> <per>')
      const [, name, capS, refillS, perS] = tokens
      if (!isValidToken(name)) fail(lineNo, `invalid policy name ${name}`)
      if (policies.has(name)) fail(lineNo, `policy ${name} is declared twice`)
      const capacity = requireUint(lineNo, capS, 'capacity', 1n)
      const refill = requireUint(lineNo, refillS, 'refill', 0n)
      const per = requireUint(lineNo, perS, 'per', 1n)
      policies.set(name, new BucketPolicy(capacity, refill, per))
    } else if (directive === 'window') {
      if (tokens.length !== 4) fail(lineNo, 'expected window <name> <limit> <span>')
      const [, name, limitS, spanS] = tokens
      if (!isValidToken(name)) fail(lineNo, `invalid policy name ${name}`)
      if (policies.has(name)) fail(lineNo, `policy ${name} is declared twice`)
