{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e3-attempts-t5/cell-A37wrX/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */
import { readFileSync } from 'node:fs'
import { simulate } from './simulate.js'
import { LimiterError } from './errors.js'

function usageFail() {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) {
  usageFail()
}

const mode = args[0]

let input
try {
  input = readFileSync(0, 'utf8')
} catch {
  input = ''
}

let results
try {
  results = simulate(input)
} catch (err) {
  if (err instanceof LimiterError) {
    process.stderr.write(`error: ${err.message}\n`)
    process.exit(2)
  }
  throw err
}

const lines = []

if (mode === 'replay') {
  for (const r of results) {
    if (r.allow) {
      lines.push(`${r.tick} ${r.key} allow`)
    } else {
      lines.push(`${r.tick} ${r.key} deny ${r.policy}`)
    }
  }
} else {
  const perKey = new Map()
  let totalAllowed = 0n
  let totalDenied = 0n
  for (const r of results) {
    let entry = perKey.get(r.key)
    if (entry === undefined) {
      entry = { allowed: 0n, denied: 0n }
      perKey.set(r.key, entry)
    }
    if (r.allow) {
      entry.allowed += 1n
      totalAllowed += 1n
    } else {
      entry.denied += 1n
      totalDenied += 1n
    }
  }
  const keys = Array.from(perKey.keys()).sort()
  for (const key of keys) {
    const entry = perKey.get(key)
    lines.push(`${key} allowed=${entry.allowed} denied=${entry.denied}`)
  }
  lines.push(`total allowed=${totalAllowed} denied=${totalDenied}`)
}

process.stdout.write(lines.length > 0 ? lines.join('\n') + '\n' : '')
process.exit(0)
"}

